/// <summary>
/// This implementation of the interface validates the values of the contract parameters.
/// </summary>
/// <returns>Boolean True, upon successful validation checks, otherwise false</returns>
public boolean validate()
{
    boolean ret = true;

    if (!itemId)
    {
        ret = checkFailed("Item number cannot be blank");
    }

    if (!warehouseId)
    {
        ret = checkFailed("Coverage warehouse cannot be blank");
    }

    if (METVendParameters::find().UpdateFromParentToTransferSites == NoYes::No)
    {
        ret = checkfailed("Metcash Accounts Payable parameter 'Update dates and states from parent to transfer sites' is not enabled to continue with Update stock availability details.");
    }

    return ret;
}
